//! Hybrid Retriever with Reciprocal Rank Fusion (RRF)
//!
//! Combines vector search results with graph traversal results
//! using RRF for optimal ranking.
impl Default for HybridRetrieverConfig {
    fn default() -> Self {
        Self {
            vector_weight: 0.7,
            graph_weight: 0.3,
            rrf_k: 60.0,
            max_results: 10,
            min_score: 0.0,
        }
    }
